    [1315]={name="Lei of Lilies",quality=4,ilvl=51,reqLevel=46,sourceType="world_drop",instructions="World drop around level 46-54.",proc="Use: Conjures a Lily Root that restores health and mana when eaten. (10 Min Cooldown)"},
    [1317]={name="Hardened Root Staff",quality=2,ilvl=27,reqLevel=22,sourceType="quest_reward",instructions="Reward from the quest 'What Comes Around...'. Pick it over the other reward choices. Starts with Guard Berton in Redridge Mountains. Objective: Bring the head of Targorr the Dread to Guard Berton in Lakeshire.",zone="The Stockade",questName="What Comes Around...",lore="Targorr the Dread served under Gath'Ilzogg as supreme Executioner. His methods were ruthless, even by filthy orc standards. Men who fought bravely to defend the Kingdom were tortured on his whim."},
    [1318]={name="Night Reaver",quality=3,ilvl=23,reqLevel=18,sourceType="raid_trash",instructions="Drops from trash in Shadowfang Keep.",zone="Shadowfang Keep",zoneOpen=true,proc="Chance on hit: Sends a shadowy bolt at the enemy causing 67 to 101 Shadow damage."},
