    [5197]={name="Cookie's Tenderizer",quality=3,ilvl=21,reqLevel=16,sourceType="boss_drop",instructions="Drops from Cookie.",zone="The Deadmines",npc="Cookie",proc="Chance on hit: Tenderize the target, increasing physical damage taken by 1 for 1 min."},
