    [12543]={name="Songstone of Ironforge",quality=3,ilvl=60,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'The Princess's Surprise'. Pick it over the other reward choices.",zone="Blackrock Depths",questName="The Princess's Surprise",lore="You ruined my life and the life of my unborn child! Return to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf."},
    [12544]={name="Thrall's Resolve",quality=3,ilvl=60,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'The Princess Saved?'. Pick it over the other reward choices.",zone="Blackrock Depths",questName="The Princess Saved?",lore="You have slain my husband! My child will be born into this world without a father. I assure you, this child will be the next ruler of the kingdom of Ironforge."},
