    [20556]={name="Wildstaff",quality=3,ilvl=52,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'Da Voodoo'. Pick it over the other reward choices. Starts with Bath'rah the Windwatcher in Alterac Mountains. Objective: Bring the voodoo feathers to Bath'rah the Windwatcher.",zone="Alterac Mountains",questName="Da Voodoo",lore="The spirit totem just isn't enough. We be needin' some voodoo magic to make it work jus' right. The trolls in the sunken temple have feathers strong with voodoo magics.",proc="Equip: Improves your chance to hit by 1.0%."},
